package io.xeros.solo;
import io.xeros.*;import io.xeros.content.skills.*;import io.xeros.content.skills.crafting.*;import io.xeros.content.skills.smithing.*;import io.xeros.model.entity.player.*;import io.xeros.model.entity.player.save.PlayerSave;import java.lang.reflect.*;import java.util.*;
public final class CraftingSmithingPlayableCheck {
 static void ok(boolean b,String s){if(!b)throw new AssertionError(s);}static Player actor(){return AttackDefencePlayableCheck.actor();}static void tick(int n){SkillsAuditCheck.tick(n);}static void clear(Player p){SkillsAuditCheck.clear(p);}static void give(Player p,int id,int n){ok(p.getItems().addItem(id,n),"Fixture "+id);}static int count(Player p,int id){return p.getItems().getInventoryCount(id);}static long xp(Player p,int s){return AttackDefencePlayableCheck.xp(p,s);}
 static void block(Player p,int mode){switch(mode){case 0:p.getHealth().setCurrentHealth(0);break;case 1:p.isDead=true;break;case 2:p.isBanking=true;break;case 3:p.isShopping=true;break;case 4:p.teleTimer=3;break;case 5:p.absX++;break;case 6:p.heightLevel++;break;case 7:p.interruptActions();break;}}
 static void craft(){
  int[][] gems={{1617,1601,43,1075},{1619,1603,34,850},{1621,1605,27,675},{1623,1607,20,500},{1625,1609,1,150},{1627,1611,13,200},{1629,1613,16,250},{1631,1615,55,1375},{6571,6573,67,1675},{19496,19493,89,2000},{23778,23783,50,50}};
  for(int[] r:gems){Player p=actor();give(p,1755,1);give(p,r[0],2);long old=xp(p,12);GemCutting.cut(p,1755,r[0]);tick(4);ok(count(p,r[1])==2&&count(p,r[0])==0&&count(p,1755)==1&&xp(p,12)-old==2*r[3],"Gem exact XP/material "+r[0]);clear(p);}
  int[] buttons={48112,48116,48120,44210,24059,48108,48124};int i=0;for(GlassData.glassData r:GlassData.glassData.values()){Player p=actor();give(p,1785,1);give(p,1775,1);long old=xp(p,12);GlassBlowing.glassBlowing(p,buttons[i++]);tick(3);ok(count(p,r.getNewId())==1&&count(p,1775)==0&&count(p,1785)==1&&xp(p,12)-old==(long)Math.floor(r.getXP()*10+1e-7),"Glass exact "+r);clear(p);}
  for(int mode=0;mode<8;mode++){Player p=actor();give(p,1755,1);give(p,1617,1);long old=xp(p,12);GemCutting.cut(p,1755,1617);block(p,mode);tick(3);ok(count(p,1617)==1&&count(p,1601)==0&&xp(p,12)==old,"Gem guard "+mode);clear(p);p=actor();give(p,1785,1);give(p,1775,1);old=xp(p,12);GlassBlowing.glassBlowing(p,48112);block(p,mode);tick(3);ok(count(p,1775)==1&&count(p,1919)==0&&xp(p,12)==old,"Glass guard "+mode);clear(p);}
  System.out.println("CRAFTING_ELEVEN_GEMS_SEVEN_GLASS_RECIPES_EXACT_MATERIALS_FOUR_CORRECTED_FRACTIONAL_XP_AND_EIGHT_CALLBACK_GUARDS_PASS");System.out.println("CRAFTING_PLAYABLE_V61_PASS");
 }
 static void smith(){
  String[] names={"bronze","iron","silver","steel","gold","mithril","adamant","rune"};int[] ore={436,440,442,440,444,447,449,451},second={438,0,0,453,0,453,453,453},qty={1,0,0,2,0,4,6,8},bar={2349,2351,2355,2353,2357,2359,2361,2363},experience={62,125,137,175,225,300,375,500};
  for(int i=0;i<names.length;i++){Player p=actor();p.playerEquipment[12]=2568;give(p,ore[i],1);if(second[i]>0)give(p,second[i],qty[i]);long old=xp(p,13);Smelting.startSmelting(p,names[i],"ONE","FURNACE");tick(1);ok(count(p,bar[i])==1&&count(p,ore[i])==0&&(second[i]==0||count(p,second[i])==0)&&xp(p,13)-old==experience[i],"Bar materials XP "+names[i]);clear(p);}
  for(int mode=0;mode<8;mode++){Player p=actor();give(p,451,1);give(p,453,8);long old=xp(p,13);Smelting.startSmelting(p,"rune","ONE","FURNACE");block(p,mode);tick(2);ok(count(p,451)==1&&count(p,453)==8&&count(p,2363)==0&&xp(p,13)==old,"Smelt guard "+mode);clear(p);}
  Player p=actor();give(p,451,1);give(p,453,7);Smelting.startSmelting(p,"rune","ONE","FURNACE");tick(1);ok(count(p,451)==1&&count(p,453)==7&&count(p,2363)==0,"Missing coal atomic");clear(p);
  p=actor();give(p,436,1);give(p,438,1);give(p,444,1);Smelting.startSmelting(p,"bronze","ALL","FURNACE");Smelting.startSmelting(p,"gold","ONE","FURNACE");tick(3);ok(count(p,2349)==0&&count(p,2357)==1&&count(p,436)==1,"Replacement smelt snapshot");clear(p);
  p=actor();give(p,451,1);give(p,453,8);p.playerLevel[13]=84;Smelting.startSmelting(p,"rune","ONE","FURNACE");tick(1);ok(count(p,451)==1,"Visible smithing level");clear(p);
  System.out.println("SMITHING_EIGHT_METAL_SMELTS_EXACT_COAL_XP_EIGHT_CALLBACK_GUARDS_MISSING_COAL_REPLACEMENT_RECIPE_AND_VISIBLE_LEVEL_PASS");System.out.println("SMITHING_PLAYABLE_V61_PASS");
 }
 static void save(){Player p=actor();p.setLoginName("skills61qa");p.setDisplayName("Skills61qa");p.setIndex(1);p.isActive=true;p.saveCharacter=true;PlayerHandler.players[1]=p;p.getPA().addSkillXPMultiplied(67.5,12,true);p.getPA().addSkillXPMultiplied(56.2,13,true);long c=xp(p,12),s=xp(p,13);give(p,1605,1);ok(PlayerSave.saveGameInstant(p),"Save");Player q=actor();q.setLoginName("skills61qa");ok(PlayerSave.loadGame(q,"skills61qa","IsolatedAudit",true).toString().equals("SUCCESS")&&xp(q,12)==c&&xp(q,13)==s&&count(q,1605)==1,"Craft Smith persistence");clear(p);clear(q);PlayerHandler.players[1]=null;System.out.println("CRAFTING_SMITHING_FRACTIONAL_XP_AND_ITEMS_REAL_SAVE_RELOAD_PASS");}
 public static void main(String[]a)throws Exception{Thread.setDefaultUncaughtExceptionHandler((t,e)->{e.printStackTrace();System.exit(1);});Thread.currentThread().setName("GameThread");System.setProperty("solo.mode","true");System.setProperty("solo.xp","1");Server.startServerless();Configuration.BONUS_SKILL=-1;Field f=io.xeros.content.boosts.Boosts.class.getDeclaredField("boosts");f.setAccessible(true);f.set(null,Collections.emptyList());craft();smith();save();System.exit(0);}
}
